ALTER TABLE tasks ADD COLUMN src TEXT NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS seen (owner TEXT NOT NULL, kind TEXT NOT NULL, key TEXT NOT NULL, PRIMARY KEY (owner, kind, key));
CREATE TABLE IF NOT EXISTS orders (owner TEXT NOT NULL, id TEXT NOT NULL, shop TEXT NOT NULL, item TEXT NOT NULL DEFAULT '', order_no TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'ordered', placed TEXT NOT NULL, updated TEXT NOT NULL, msg_id TEXT NOT NULL DEFAULT '', hidden INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (owner, id));
